import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def set_values(instance, values):
    ok = execute_tool('editor_toolset.toolsets.object.ObjectTools.set_properties', json.dumps({'instance': instance, 'values': json.dumps(values)}))['returnValue']
    if not ok:
        raise RuntimeError('Failed to set properties on ' + instance.get('refPath', 'unknown'))

def compile_blueprint(path):
    execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.compile_blueprint', json.dumps({'blueprint': load(path), 'warnings_as_errors': True}))

def configure(prefix, item, equipment, instance, ability_set, fire, reload, damage, presentation, fire_tag):
    item_path = prefix + '/' + item
    equipment_path = prefix + '/' + equipment
    instance_path = prefix + '/' + instance
    ability_set_path = prefix + '/' + ability_set
    fire_path = prefix + '/' + fire
    reload_path = prefix + '/' + reload
    damage_path = prefix + '/' + damage
    presentation_path = prefix + '/' + presentation

    set_values({'refPath': item_path + '.Default__' + item + '_C:InventoryFragment_EquippableItem_0'}, {
        'equipmentDefinition': {'refPath': equipment_path + '.' + equipment + '_C'}
    })
    set_values(load(equipment_path), {
        'instanceType': {'refPath': instance_path + '.' + instance + '_C'},
        'abilitySetsToGrant': [{'refPath': ability_set_path + '.' + ability_set}],
        'actorsToSpawn': [{
            'actorToSpawn': {'refPath': presentation_path + '.' + presentation + '_C'},
            'attachSocket': 'weapon_r',
            'attachTransform': {
                'location': {'x': 0.0, 'y': 0.0, 'z': 0.0},
                'rotation': {'pitch': 0.0, 'yaw': -90.0, 'roll': 0.0},
                'scale': {'x': 1.0, 'y': 1.0, 'z': 1.0}
            }
        }]
    })
    ability = load(ability_set_path)
    set_values(ability, {'grantedGameplayAbilities': []})
    set_values(ability, {'grantedGameplayAbilities': [
        {'ability': {'refPath': fire_path + '.' + fire + '_C'}, 'abilityLevel': 1, 'inputTag': {'tagName': fire_tag}},
        {'ability': {'refPath': reload_path + '.' + reload + '_C'}, 'abilityLevel': 1, 'inputTag': {'tagName': 'InputTag.Weapon.Reload'}},
        {'ability': {'refPath': '/Game/Weapons/GA_Weapon_AutoReload.GA_Weapon_AutoReload_C'}, 'abilityLevel': 1, 'inputTag': {'tagName': 'None'}}
    ]})
    set_values(load(fire_path), {'gE_Damage': {'refPath': damage_path + '.' + damage + '_C'}})

    blueprints = [item_path, equipment_path, instance_path, fire_path, reload_path, damage_path, presentation_path]
    for path in blueprints:
        compile_blueprint(path)
    return blueprints + [ability_set_path]

def run():
    rifle = configure(
        '/ExtractionOps/Weapons/Rifle',
        'ID_ExtractionRifle', 'WID_ExtractionRifle', 'B_WeaponInstance_ExtractionRifle',
        'AbilitySet_ExtractionRifle', 'GA_Weapon_Fire_ExtractionRifle',
        'GA_Weapon_Reload_ExtractionRifle', 'GE_Damage_ExtractionRifle',
        'B_ExtractionRifle', 'InputTag.Weapon.FireAuto')
    shotgun = configure(
        '/ExtractionOps/Weapons/Shotgun',
        'ID_ExtractionShotgun', 'WID_ExtractionShotgun', 'B_WeaponInstance_ExtractionShotgun',
        'AbilitySet_ExtractionShotgun', 'GA_Weapon_Fire_ExtractionShotgun',
        'GA_Weapon_Reload_ExtractionShotgun', 'GE_Damage_ExtractionShotgun',
        'B_ExtractionShotgun', 'InputTag.Weapon.FireAuto')
    paths = rifle + shotgun
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']:
        raise RuntimeError('Failed to save configured Week 3 assets')
    return {'configured': paths, 'saved': True}
